package com.supermarkettracker.infrastructure.persistence.adapter;
import com.supermarkettracker.domain.model.*; import com.supermarkettracker.domain.model.valueobject.*; import com.supermarkettracker.domain.repository.UsuarioRepository; import com.supermarkettracker.infrastructure.persistence.mapper.UsuarioPersistenceMapper; import com.supermarkettracker.infrastructure.persistence.repository.UsuarioJpaRepository; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class UsuarioRepositoryJpaAdapter implements UsuarioRepository { private final UsuarioJpaRepository jpa; private final UsuarioPersistenceMapper mapper; public UsuarioRepositoryJpaAdapter(UsuarioJpaRepository jpa, UsuarioPersistenceMapper mapper){this.jpa=jpa;this.mapper=mapper;} public Usuario salvar(Usuario x){return mapper.toDomain(jpa.save(mapper.toEntity(x)));} public Optional<Usuario> buscarPorId(Identificador id){return jpa.findById(id.valor()).map(mapper::toDomain);} public Optional<Usuario> buscarPorEmail(Email email){return jpa.findByEmail(email.valor()).map(mapper::toDomain);} }
